<script setup lang="ts">import {money} from '../utils/format';defineProps<{result:any}>();const labels:Record<string,string>={inserted:'已写入',duplicate:'重复',quarantined:'已隔离'};const reasonLabels:Record<string,string>={duplicate_existing:'与已有分录内容一致',duplicate_in_upload:'本次上传内内容一致',conflict_existing:'编号已存在但内容冲突，留待核对',conflict_in_upload:'本次上传内同编号内容冲突，留待核对',invalid_amount:'金额不是正整数分',amount_out_of_range:'金额分超出范围',invalid_date:'日期无效',column_mismatch:'列数与表头不一致'};function codes(row:any){return (row.reasons||[]).map((c:string)=>reasonLabels[c]||c).join('、')}</script><template><section v-if="result" class="import-result"><div class="import-totals"><div><small>原始行数</small><strong>{{result.totals.total_rows}}</strong></div><div><small>已写入</small><strong>{{result.totals.inserted}}</strong></div><div><small>重复</small><strong>{{result.totals.duplicate}}</strong></div><div><small>已隔离</small><strong>{{result.totals.quarantined}}</strong></div></div><p class="method-note">已写入 {{result.totals.inserted}} + 重复 {{result.totals.duplicate}} + 隔离 {{result.totals.quarantined}} = {{result.totals_check.inserted_plus_duplicate_plus_quarantined}} / 原始 {{result.totals.total_rows}} 行 <span :class="result.totals_check.complete?'ok':'bad'">{{result.totals_check.complete?'✓ 合计一致':'✗ 合计不一致'}}</span>；其中隔离行含内容冲突 {{result.totals.conflict}} 条，冲突不覆盖原记录。</p><p class="method-note">本次导入 {{result.actor||'—'}} · {{result.created_at}} · {{result.source==='initial'?'首次建档':'续传'}}</p><div class="table-wrap"><table><thead><tr><th>行号</th><th>分录ID</th><th>结果</th><th>原因</th><th>金额元</th><th>原行文本</th></tr></thead><tbody><tr v-for="row in result.rows" :key="row.line_no" :class="['import-row',row.outcome]"><td>{{row.line_no}}</td><td>{{row.external_id||'—'}}</td><td><span :class="['stage-pill',row.outcome]">{{labels[row.outcome]||row.outcome}}</span></td><td><span class="row-note" :title="row.reason">{{row.reason||'—'}}</span><small v-if="codes(row)">{{codes(row)}}</small></td><td>{{row.parsed?money(row.parsed.amount_cents):'—'}}</td><td><code class="raw-line">{{row.raw_text}}</code></td></tr></tbody></table></div></section></template>
